48					[`${SLOT}|123|music-module|voice|joinVoiceChannel|UNAVAILABLE`, 1]
49				])
50			);
51			// Nada que borrar todavía: la ventana acaba de empezar.
52			expect(writeWindow.mock.calls[0][1]).toEqual([]);
