import * as grpc from "@grpc/grpc-js";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { grpcStatusLabel } from "./RequestMetrics.js";
import type * as RequestMetricsModule from "./RequestMetrics.js";

// `redisAdapter` abre conexiones ioredis al importarse; aquí sólo interesa el
// lote que se le entrega.
const { writeWindow } = vi.hoisted(() => ({ writeWindow: vi.fn() }));

vi.mock("../infrastructure/redis/index.js", () => ({
	redisAdapter: { cache: { gateway: { requestMetrics: { writeWindow } } } }
}));

// 2026-08-11T12:34:56.789Z, desalineado con el slot de un minuto a propósito.
const NOW = 1_786_912_496_789;
const SLOT = 1_786_912_440_000;

describe("recordGatewayRequest", () => {
	// El contador es estado de proceso (el gateway es un único proceso). Cada
	// caso reimporta el módulo para arrancar con la ventana vacía; si no, el
	// slot escrito por el test anterior sigue pendiente de borrado en éste.
	let metrics: typeof RequestMetricsModule;

	beforeEach(async () => {
		vi.useFakeTimers();
		vi.setSystemTime(NOW);
		writeWindow.mockClear();
		writeWindow.mockResolvedValue(undefined);
		vi.resetModules();
		metrics = await import("./RequestMetrics.js");
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("aggregates repeated combinations into one field of the current slot", async () => {
		metrics.recordGatewayRequest("123", "music-module", "voice", "joinVoiceChannel", "ok");
		metrics.recordGatewayRequest("123", "music-module", "voice", "joinVoiceChannel", "ok");
		metrics.recordGatewayRequest("123", "music-module", "voice", "joinVoiceChannel", "UNAVAILABLE");

		await metrics.flushGatewayRequestMetrics();

		expect(writeWindow).toHaveBeenCalledTimes(1);
		expect(writeWindow.mock.calls[0][0]).toEqual(
			new Map([
				[`${SLOT}|123|music-module|voice|joinVoiceChannel|ok`, 2],
				[`${SLOT}|123|music-module|voice|joinVoiceChannel|UNAVAILABLE`, 1]
			])
		);
		// Nada que borrar todavía: la ventana acaba de empezar.
		expect(writeWindow.mock.calls[0][1]).toEqual([]);

		// El buffer se sustituye en el volcado: un segundo flush sin tráfico no
		// puede reenviar los mismos contadores.
		await metrics.flushGatewayRequestMetrics();
		expect(writeWindow).toHaveBeenCalledTimes(1);
	});

	it("deletes the fields of a slot once it leaves the rolling window", async () => {
		metrics.recordGatewayRequest("123", "music-module", "guild", "getGuild", "ok");
		await metrics.flushGatewayRequestMetrics();

		// 60 minutos después, el slot original ya no cabe en la ventana.
		vi.setSystemTime(NOW + 60 * 60_000);
		metrics.recordGatewayRequest("123", "music-module", "guild", "getGuild", "ok");
		await metrics.flushGatewayRequestMetrics();

		expect(writeWindow.mock.calls[1][1]).toEqual([`${SLOT}|123|music-module|guild|getGuild|ok`]);

		// Ya borrado: no se vuelve a pedir en el siguiente volcado.
		vi.setSystemTime(NOW + 61 * 60_000);
		metrics.recordGatewayRequest("123", "music-module", "guild", "getGuild", "ok");
		await metrics.flushGatewayRequestMetrics();
		expect(writeWindow.mock.calls[2][1]).toEqual([]);
	});

	it("keeps the expired fields pending when the flush fails", async () => {
		metrics.recordGatewayRequest("123", "music-module", "guild", "getGuild", "ok");
		await metrics.flushGatewayRequestMetrics();

		writeWindow.mockRejectedValueOnce(new Error("Connection is closed."));
		vi.setSystemTime(NOW + 60 * 60_000);
		await expect(metrics.flushGatewayRequestMetrics()).resolves.toBeUndefined();

		// El borrado no se dio por hecho: se reintenta en el volcado siguiente.
		await metrics.flushGatewayRequestMetrics();
		expect(writeWindow.mock.calls[2][1]).toEqual([`${SLOT}|123|music-module|guild|getGuild|ok`]);
	});

	it("normalises a missing bot or caller instead of writing an empty dimension", async () => {
		metrics.recordGatewayRequest("", "", "guild", "getGuild", "ok");

		await metrics.flushGatewayRequestMetrics();

		expect(writeWindow.mock.calls[0][0]).toEqual(new Map([[`${SLOT}|unknown|gateway|guild|getGuild|ok`, 1]]));
	});
});

describe("grpcStatusLabel", () => {
	it("names the numeric grpc status of every rejection path of dispatch", () => {
		expect(grpcStatusLabel({ code: grpc.status.UNAVAILABLE })).toBe("UNAVAILABLE");
		expect(grpcStatusLabel({ code: grpc.status.DEADLINE_EXCEEDED })).toBe("DEADLINE_EXCEEDED");
		expect(grpcStatusLabel({ code: grpc.status.INVALID_ARGUMENT })).toBe("INVALID_ARGUMENT");
	});

	it("falls back to UNKNOWN for anything without a usable code", () => {
		expect(grpcStatusLabel(new Error("boom"))).toBe("UNKNOWN");
		expect(grpcStatusLabel(undefined)).toBe("UNKNOWN");
		// `grpc.status.OK` es 0: no debe caer en el fallback por ser falsy.
		expect(grpcStatusLabel({ code: grpc.status.OK })).toBe("OK");
	});
});

